def iter_config_dirs(self) -> Iterator[str]:
    """:yield: all user and site configuration directories."""
    yield self.user_config_dir
    # Omit site config dir if it matches user config dir (duplicate when use_site_for_root is active)
    for d in self._site_config_dirs:
        if d != self.user_config_dir:
            yield d

def iter_data_dirs(self) -> Iterator[str]:
    """:yield: all user and site data directories."""
    yield self.user_data_dir
    # Omit site data dir if it matches user data dir (duplicate when use_site_for_root is active)
    for d in self._site_data_dirs:
        if d != self.user_data_dir:
            yield d
